# ── Read today's bank balance change from Xero ──
XERO = "xero-accounting"
TOOL = "get_xero_bank_balance_difference"
ORG_TOOL = "get_organisation"
CONN_TOOL = "list_connections"
# A movement smaller than half a cent is rounding, not a change.
EPS = 0.005


def _err(exc):
    msg = str(exc)
    if msg.startswith("tool_error: "):
        msg = msg[len("tool_error: "):]
    if "no usable credential" in msg or "credential unavailable" in msg:
        return "the Xero connection needs connecting (Settings -> Connections -> xero-accounting)"
    return msg[:200]


def _plural(n, word):
    return str(n) + " " + word + ("" if n == 1 else "s")


change = {}
problem = ""

# Which organisation to read. A dashboard tile follows the organisation picker on the dashboard; an
# automation has no picker, so without this it reads whichever organisation the connection happens to
# default to - which is not necessarily the one the tile is showing.
want = str(params.get("xero_org") or "").strip()
tenant = ""
if want:
    try:
        conns = api.connectors.invoke(server=XERO, tool=CONN_TOOL, args={})
    except Exception as exc:
        problem = "Couldn't list the Xero organisations: " + _err(exc) + "."
    else:
        # list_connections answers {activeTenantId, tenants:[...]}, whatever its description says. A bare
        # list is accepted too, so this keeps working if that ever changes.
        rows = conns.get("tenants") if isinstance(conns, dict) else conns
        if not isinstance(rows, list):
            rows = []
        names = []
        ids = {}
        for row in rows:
            if not isinstance(row, dict):
                continue
            tenant_name = str(row.get("tenantName") or "").strip()
            if tenant_name:
                names.append(tenant_name)
                ids[tenant_name] = str(row.get("tenantId") or "")
        # Part of the name is enough, so nobody has to retype a legal name exactly. A whole name still wins
        # outright, so an organisation whose name sits inside a longer one is still reachable.
        hits = [n for n in names if n.lower() == want.lower()]
        if not hits:
            hits = [n for n in names if want.lower() in n.lower()]
        if len(hits) == 1:
            tenant = ids.get(hits[0]) or ""
        elif len(hits) > 1:
            problem = (want + " matches more than one connected Xero organisation: " + ", ".join(hits) +
                       ". Use more of the name.")
        elif names:
            problem = ("No connected Xero organisation matches " + want + ". Connected: " +
                       ", ".join(names) + ". Check Settings -> Connections -> xero-accounting.")
        else:
            problem = ("Xero didn't name any connected organisations, so " + want +
                       " couldn't be matched. Check Settings -> Connections -> xero-accounting.")

call_args = {"xero_tenant_id": tenant} if tenant else {}

if not problem:
    try:
        res = api.connectors.invoke(server=XERO, tool=TOOL, args=call_args)
    except Exception as exc:
        problem = "Couldn't read the bank balances: " + _err(exc) + "."
    else:
        # The tool returns {summary, defaultAccountId, accounts[]}; anything else means the shape changed.
        change = res if isinstance(res, dict) else {}
        if not isinstance(change.get("accounts"), list):
            change = {}
            problem = "Xero answered, but not with the bank balance figures this report needs."

accounts = change.get("accounts") or []
if not problem and not accounts:
    problem = "No bank accounts came back from Xero, so there is nothing to report."

# Which Xero organisation these figures actually came from. A tile reads the signed-in person's own Xero
# connection and an automation reads the workspace's, so the two can sit on different organisations and
# quietly disagree. Naming the org on the report makes that visible instead of silent.
org_name = ""
if not problem:
    try:
        org_res = api.connectors.invoke(server=XERO, tool=ORG_TOOL, args=call_args)
    except Exception:
        org_name = ""
    else:
        wrap = org_res if isinstance(org_res, dict) else {}
        orgs = wrap.get("Organisations")
        if not isinstance(orgs, list):
            orgs = org_res if isinstance(org_res, list) else []
        first = orgs[0] if orgs else {}
        if isinstance(first, dict):
            org_name = str(first.get("Name") or first.get("LegalName") or "").strip()

moved = [a for a in accounts if abs(float(a.get("difference") or 0)) >= EPS]
head = str((change.get("summary") or {}).get("subtitle") or "")
summary = problem or ("Read " + _plural(len(accounts), "bank account") +
                      (" in " + org_name if org_name else " (Xero didn't name the organisation)") + "; " +
                      _plural(len(moved), "account") + " moved. " + head)
